// Exact quartic certificate: constant span.
#include "s61_binary_deeper_quartic_field_20261101.hpp"
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);flint_set_num_threads(2);{ifstream in(argv[1]);int nr,nc;in>>nr>>nc;vector<Row>A(nr),B;vector<int>pivs;for(auto&row:A){int n;in>>n;for(int j=0;j<n;j++){int k;in>>k;Rat c;readpoly(in,c.n);readpoly(in,c.d);c.reduce();row.emplace(k,std::move(c));}}
while(true){int best=-1,col=-1;for(int i=0;i<nr&&best<0;i++)for(auto&[j,v]:A[i])if(fmpq_mpoly_is_fmpq(v.n,ctx)&&fmpq_mpoly_is_fmpq(v.d,ctx)){best=i;col=j;break;}if(best<0)break;Row row=std::move(A[best]);Rat c=row[col];for(auto&[j,v]:row)v=divi(v,c);for(auto&other:A){auto it=other.find(col);if(it==other.end())continue;Rat h=it->second;for(auto&[j,v]:row){Rat z=sub(other[j],mul(h,v));if(z.zero())other.erase(j);else other[j]=std::move(z);}}pivs.push_back(col);B.push_back(std::move(row));if(B.size()%25==0)cerr<<"RANK "<<B.size()<<'\n';}
ofstream out(argv[2]);assert(out);out<<B.size()<<' '<<nc<<'\n';for(int i=0;i<int(B.size());i++){out<<pivs[i]<<' '<<B[i].size()<<'\n';for(auto&[j,c]:B[i]){out<<j<<'\n';writepoly(out,c.n);writepoly(out,c.d);}}cerr<<"CONSTANT RANK "<<B.size()<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
